//! 📤️ The original paged tail stays resident through denied and paid same-Source movement.
use semio_framework_value_paged_list::{PagedList,PagedListReservationOutcome,PagedListReleaseOutcome};
use semio_framework_value_control_contract::{OriginalEffectReply,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn fund(bank:&EffectBank,demand:RetirementDemand)->RetainedCloneGrant{let mut grant=bank.loan(1,demand.copy_bytes);assert!(grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth);grant.maximum_capacity_bytes=demand.capacity_bytes;grant.maximum_release_bytes=demand.release_bytes;grant.maximum_depth=demand.depth;grant}
fn progress(p:semio_framework_value_paged_list::PagedListProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes}}
#[test]
fn native_tail_pop_retains_original_on_denial_and_records_exact_work(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️reservation/↔️transfer/🔣️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut list=PagedList::<u8,{usize::MAX}>::new();
 while !list.has_reserved_slot(){let demand=RetirementDemand{copy_bytes:list.next_reserve_copy_byte_demand().unwrap(),capacity_bytes:list.next_allocation_bytes().unwrap(),depth:list.next_reserve_depth_demand().unwrap(),..Default::default()};let work=list.reserve_one_work_demand().unwrap();let grant=fund(&bank,demand);let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|RetainedWorkPoll::Complete(list.reserve_one(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native reservation remained pending")};let PagedListReservationOutcome::Ready(p)=turn.result.unwrap()else{panic!("quoted native reservation denied")};if let Some(bytes)=actual{assert_eq!(bytes,heap.0)}assert_eq!(bank.take_admitted(),Some(true));bank.post(progress(p),grant,heap);}
 let mut input=Some(law["value"].as_u64().unwrap() as u8);let demand=list.adoption_demand(&input).unwrap();let grant=fund(&bank,demand);let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.adopt_reserved(&mut input,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native placement remained pending")};let p=turn.result.unwrap();assert!(p.progressed);assert!(input.is_none());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress(p),grant,heap);
 let demand=list.pop_source_demand().unwrap();let work=list.pop_source_work_demand().unwrap();assert_eq!(work,law["cases"][1]["appendWork"].as_u64().unwrap());for maximum in [0,1,work-1]{let grant=fund(&bank,demand);let mut output=None;let mut reply=None;let((poll,actual),heap)=observe(||bank.run(grant,maximum,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(list.pop_into(&mut output,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted pop denial remained pending")};assert_eq!(turn.work,0);assert!(output.is_none());assert_eq!(list.len(),1);assert_eq!(reply.as_ref().unwrap().as_ref().unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),grant,heap);}
 for denied in [RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..fund(&bank,demand)},RetainedCloneGrant{maximum_depth:demand.depth-1,..fund(&bank,demand)}]{let mut output=None;let mut reply=None;let((poll,actual),heap)=observe(||bank.run(denied,work,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(list.pop_into(&mut output,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted physical denial remained pending")};assert_eq!(turn.work,0);assert!(output.is_none());assert_eq!(list.len(),1);assert_eq!(reply.as_ref().unwrap().as_ref().unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied,heap);}
 let occupied_grant=fund(&bank,demand);let mut occupied=Some(99);let mut occupied_reply=None;let((poll,actual),heap)=observe(||bank.run(occupied_grant,work,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut occupied_reply).unwrap();drop(list.pop_into(&mut occupied,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("occupied-output refusal remained pending")};assert_eq!(turn.work,0);assert!(occupied_reply.as_ref().unwrap().is_err());assert_eq!(occupied,Some(99));assert_eq!(list.len(),1);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),occupied_grant,heap);
 let grant=fund(&bank,demand);let mut output=None;let mut reply=None;let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(list.pop_into(&mut output,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("paid pop remained pending")};assert_eq!(turn.work,u128::from(work));assert_eq!(output,Some(law["value"].as_u64().unwrap() as u8));assert!(list.is_empty());let step=reply.as_ref().unwrap().as_ref().unwrap();assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap);
 while !list.terminal_is_empty(){let demand=RetirementDemand{copy_bytes:list.next_release_copy_byte_demand().unwrap(),release_bytes:list.next_release_allocation_bytes().unwrap(),depth:list.next_release_depth_demand().unwrap(),..Default::default()};let grant=fund(&bank,demand);let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.release_empty_page(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native release remained pending")};let PagedListReleaseOutcome::Ready(p)=turn.result.unwrap()else{panic!("quoted native release denied")};assert!(p.progressed);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress(p),grant,heap);}
}

#[test]
fn native_tail_pop_records_each_actual_radix_level(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️reservation/↔️transfer/🔣️pop-radix.json")).unwrap();for case in law["cases"].as_array().unwrap(){let count=case["length"].as_u64().unwrap() as usize;let(list,seed_heap)=observe(||{let mut list=PagedList::<u8,64>::with_page_items(law["pageItems"].as_u64().unwrap() as usize);for value in 0..count{list.push(value as u8)}list});let mut wallet=Wallet::from_profile(&law["stock"]);let initial=wallet.loan(1,64);wallet.post(RetainedCloneProgress{retained_capacity_bytes:seed_heap.0,released_bytes:seed_heap.1,..Default::default()},0,initial,seed_heap);let mut bank=EffectBank::new(wallet);let mut list=list;let demand=list.pop_source_demand().unwrap();let work=list.pop_source_work_demand().unwrap();assert_eq!(work,case["work"].as_u64().unwrap());let denied=fund(&bank,demand);let mut denied_output=None;let mut denied_reply=None;let((poll,actual),heap)=observe(||bank.run(denied,work-1,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut denied_reply).unwrap();drop(list.pop_into(&mut denied_output,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted radix pop denial remained pending")};assert_eq!(turn.work,0);assert!(denied_output.is_none());assert_eq!(list.len(),count);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied,heap);let grant=fund(&bank,demand);let mut output=None;let mut reply=None;let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(list.pop_into(&mut output,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native radix pop remained pending")};assert_eq!(turn.work,u128::from(work));assert_eq!(output,Some((count-1) as u8));assert_eq!(list.len(),count-1);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(reply.as_ref().unwrap().as_ref().unwrap().progress(),grant,heap);while !list.is_empty(){let grant=bank.loan(64,4096);let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.discard_plain_tail(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("plain fixture cleanup remained pending")};let progress=turn.result.unwrap();assert!(progress.copied_items>0);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap)}while !list.terminal_is_empty(){let demand=RetirementDemand{copy_bytes:list.next_release_copy_byte_demand().unwrap(),release_bytes:list.next_release_allocation_bytes().unwrap(),depth:list.next_release_depth_demand().unwrap(),..Default::default()};let grant=fund(&bank,demand);let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.release_empty_page(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("radix backing release remained pending")};let PagedListReleaseOutcome::Ready(p)=turn.result.unwrap()else{panic!("quoted radix release denied")};assert!(p.progressed);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress(p),grant,heap)}assert_eq!(observe(||drop(list)).1,(0,0));}
}
